/*
 * ESP32 SD Card Songs Player with IR Remote Control
 *
 * Hardware:
 *   ESP32 DevKit V1
 *   Micro SD Card Module (SPI)
 *   MAX98357A I2S Amplifier
 *   4 Ohm Speaker
 *   TSOP4838 IR Receiver
 *   IR Remote Control
 *
 * Pin Mapping:
 *   SD Card:  CS=D5, SCK=D18, MOSI=D23, MISO=D19
 *   I2S Amp:  BCLK=D26, LRC=D25, DIN=D22
 *   IR:       Receiver OUT=D15
 *
 * IR Remote Buttons:
 *   PLAY  = Play/Pause
 *   NEXT  = Next song
 *   PREV  = Previous song
 *   +     = Volume up
 *   -     = Volume down
 *   CH    = Toggle repeat mode
 *   EQ    = Shuffle
 *
 * Usage:
 *   1. Right-click the SD Card component
 *   2. Select 'Upload files to SD card'
 *   3. Upload .pcm files (16-bit, 44100Hz, mono)
 *   4. Optionally upload playlist.txt (one song name per line)
 *   5. Press Run
 *   6. Use IR Remote to control playback
 *
 * To convert audio files to PCM format:
 *   ffmpeg -i song.mp3 -f s16le -ar 44100 -ac 1 song.pcm
 */

#include <WiFi.h>
#include <driver/i2s.h>
#include <SD.h>
#include <SPI.h>
#include <IRremote.h>

// --- Pin Definitions ---
#define SD_CS_PIN     5
#define I2S_BCLK_PIN  26
#define I2S_LRCK_PIN  25
#define I2S_DOUT_PIN  22
#define IR_RECV_PIN   15

// --- I2S Config ---
#define I2S_PORT      I2S_NUM_0
#define I2S_BUF_SIZE  1024
#define I2S_BUF_COUNT 4
#define SAMPLE_RATE   44100

// --- IR Remote Button Codes (NEC) ---
#define IR_CODE_PLAY   0x43
#define IR_CODE_NEXT   0x40
#define IR_CODE_PREV   0x44
#define IR_CODE_VOL_UP 0x15
#define IR_CODE_VOL_DN 0x07
#define IR_CODE_CH     0x46
#define IR_CODE_EQ     0x09
#define IR_CODE_0      0x16
#define IR_CODE_100    0x19
#define IR_CODE_200    0x0D

// --- Song Management ---
#define MAX_SONGS 30
String songList[MAX_SONGS];
int songCount = 0;
int currentSong = 0;
bool isPlaying = false;
bool repeatAll = true;
int volume = 80;  // 0-100%

  // --- Audio Buffer ---
int16_t audioBuf[I2S_BUF_SIZE];
int audioBufBytes = I2S_BUF_SIZE * 2;
File songFile;
unsigned long lastIrCheck = 0;
#define IR_CHECK_INTERVAL 50  // ms

// --- IR Receiver ---
IRrecv irrecv(IR_RECV_PIN);
decode_results irCode;

void setupI2S() {
  i2s_config_t i2s_config = {
    .mode = (i2s_mode_t)(I2S_MODE_MASTER | I2S_MODE_TX),
    .sample_rate = SAMPLE_RATE,
    .bits_per_sample = I2S_BITS_PER_SAMPLE_16BIT,
    .channel_format = I2S_CHANNEL_FMT_ONLY_LEFT,
    .communication_format = I2S_COMM_FORMAT_STAND_I2S,
    .intr_alloc_flags = ESP_INTR_FLAG_LEVEL1,
    .dma_buf_count = I2S_BUF_COUNT,
    .dma_buf_len = I2S_BUF_SIZE,
    .use_apll = false,
    .tx_desc_auto_clear = true,
  };

  i2s_pin_config_t pin_config = {
    .bck_io_num = I2S_BCLK_PIN,
    .ws_io_num = I2S_LRCK_PIN,
    .data_out_num = I2S_DOUT_PIN,
    .data_in_num = I2S_PIN_NO_CHANGE,
  };

  i2s_driver_install(I2S_PORT, &i2s_config, 0, NULL);
  i2s_set_pin(I2S_PORT, &pin_config);
  i2s_zero_dma_buffer(I2S_PORT);
  Serial.println('[I2S] Initialized: 44100Hz 16-bit Mono');
}

void scanSDCard() {
  songCount = 0;
  File root = SD.openDir("/");
  if (!root) {
    Serial.println('[SD] Failed to open root directory');
    return;
  }

  // First check for playlist.txt
  if (SD.exists("playlist.txt")) {
    File pl = SD.open("playlist.txt", FILE_READ);
    if (pl) {
      Serial.println('[SD] Reading playlist.txt...');
      while (pl.available() && songCount < MAX_SONGS) {
        String line = "";
        while (pl.available()) {
          int ch = pl.read();
          if (ch < 0) break;
          if (ch == '\n') break;
          line += String.fromCharCode(ch);
        }
        line.trim();
        if (line.length() > 0) {
          if (SD.exists(line)) {
            songList[songCount++] = line;
            Serial.println('  ' + String(songCount) + '. ' + line);
          } else {
            Serial.println('  [SKIP] File not found: ' + line);
          }
        }
      }
      pl.close();
    }
  }

  // If no playlist or playlist was empty, scan for .pcm files
  if (songCount == 0) {
    Serial.println('[SD] No playlist found, scanning for .pcm files...');
    File entry = root.openNextFile();
    while (entry) {
      if (!entry.isDirectory()) {
        String name = entry.name();
        if (name.endsWith(".pcm") || name.endsWith(".raw") || name.endsWith(".wav")) {
          if (songCount < MAX_SONGS) {
            songList[songCount++] = name;
            Serial.println('  ' + String(songCount) + '. ' + name + ' (' + String(entry.size()) + ' bytes)');
          }
        }
      }
      entry.close();
      entry = root.openNextFile();
    }
  }

  root.close();

  if (songCount == 0) {
    Serial.println('[SD] No audio files found!');
    Serial.println('[SD] Right-click the SD Card component to upload .pcm files.');
  } else {
    Serial.println('[SD] Found ' + String(songCount) + ' song(s)');
  }
}

void applyVolume(int16_t* buf, int count) {
  float gain = volume / 100.0;
  for (int i = 0; i < count; i++) {
    buf[i] = (int16_t)(buf[i] * gain);
  }
}

void openSong(int index) {
  if (songFile) songFile.close();
  if (index < 0 || index >= songCount) return;

  String filename = songList[index];
  Serial.println('[Player] Opening: ' + filename);
  songFile = SD.open(filename, FILE_READ);
  if (!songFile) {
    Serial.println('[Player] Failed to open: ' + filename);
  } else {
    Serial.println('[Player] Size: ' + String(songFile.size()) + ' bytes');
    Serial.println('[Player] Duration: ' + String(songFile.size() / (SAMPLE_RATE * 2)) + ' sec');
  }
}

void nextSong() {
  currentSong = (currentSong + 1) % songCount;
  Serial.println('[Player] Next: ' + String(currentSong + 1) + '/' + String(songCount) + ' - ' + songList[currentSong]);
  openSong(currentSong);
}

void prevSong() {
  currentSong = (currentSong - 1 + songCount) % songCount;
  Serial.println('[Player] Prev: ' + String(currentSong + 1) + '/' + String(songCount) + ' - ' + songList[currentSong]);
  openSong(currentSong);
}

void handleIRRemote() {
  if (!irrecv.decode(&irCode)) return;

  unsigned long code = irCode.value;
  irrecv.resume();

  // Ignore repeat codes
  if (code == 0xFFFFFFFF) return;

  Serial.println('[IR] Code: 0x' + String((uint32_t)code, HEX));

  switch (code) {
    case IR_CODE_PLAY:
      isPlaying = !isPlaying;
      Serial.println('[IR] ' + String(isPlaying ? 'PLAY' : 'PAUSE'));
      if (isPlaying && !songFile && songCount > 0) {
        openSong(currentSong);
      }
      break;

    case IR_CODE_NEXT:
      if (songCount > 0) {
        nextSong();
        isPlaying = true;
      }
      break;

    case IR_CODE_PREV:
      if (songCount > 0) {
        prevSong();
        isPlaying = true;
      }
      break;

    case IR_CODE_VOL_UP:
      volume = min(100, volume + 10);
      Serial.println('[IR] Volume: ' + String(volume) + '%');
      break;

    case IR_CODE_VOL_DN:
      volume = max(0, volume - 10);
      Serial.println('[IR] Volume: ' + String(volume) + '%');
      break;

    case IR_CODE_CH:
      repeatAll = !repeatAll;
      Serial.println('[IR] Repeat: ' + String(repeatAll ? 'ALL' : 'OFF'));
      break;

    case IR_CODE_EQ:
      if (songCount > 1) {
        int newSong;
        do {
          newSong = random(0, songCount);
        } while (newSong == currentSong && songCount > 1);
        currentSong = newSong;
        Serial.println('[IR] Shuffle: ' + String(currentSong + 1) + '/' + String(songCount) + ' - ' + songList[currentSong]);
        openSong(currentSong);
        isPlaying = true;
      }
      break;

    case IR_CODE_0:
      // Stop
      isPlaying = false;
      if (songFile) songFile.close();
      i2s_zero_dma_buffer(I2S_PORT);
      Serial.println('[IR] STOP');
      break;

    case IR_CODE_100:
      volume = 100;
      Serial.println('[IR] Volume: 100%');
      break;

    case IR_CODE_200:
      volume = 50;
      Serial.println('[IR] Volume: 50%');
      break;

    default:
      // Map number buttons 1-9 to song selection
      if (code >= 0x0C && code <= 0x0C + 8 && songCount > 0) {
        int num = (code - 0x0C) + 1;
        if (num <= songCount) {
          currentSong = num - 1;
          Serial.println('[IR] Song ' + String(num) + ': ' + songList[currentSong]);
          openSong(currentSong);
          isPlaying = true;
        }
      }
      break;
  }
}

void setup() {
  Serial.begin(115200);
  Serial.println();
  Serial.println('========================================');
  Serial.println(' ESP32 SD Card Songs Player');
  Serial.println('========================================');
  Serial.println();

  // Initialize I2S
  setupI2S();

  // Initialize SD Card
  Serial.println('[SD] Initializing SD card (CS=D5)...');
  if (!SD.begin(SD_CS_PIN)) {
    Serial.println('[SD] FAILED! Check wiring and CS pin.');
    Serial.println('[SD] Make sure files are uploaded to the SD Card component.');
  } else {
    Serial.println('[SD] Card initialized successfully.');
  }

  // Initialize IR Receiver
  irrecv.enableIRIn();
  Serial.println('[IR] Receiver initialized on pin ' + String(IR_RECV_PIN));

  // Scan for songs
  Serial.println();
  scanSDCard();

  // Print IR remote instructions
  Serial.println();
  Serial.println('--- IR Remote Controls ---');
  Serial.println('  PLAY  = Play / Pause');
  Serial.println('  NEXT  = Next song');
  Serial.println('  PREV  = Previous song');
  Serial.println('  +     = Volume up (+10%)');
  Serial.println('  -     = Volume down (-10%)');
  Serial.println('  CH    = Toggle repeat');
  Serial.println('  EQ    = Shuffle');
  Serial.println('  0     = Stop');
  Serial.println('  100+  = Volume 100%');
  Serial.println('  200+  = Volume 50%');
  Serial.println('  1-9   = Jump to song #');
  Serial.println('--------------------------');
  Serial.println();

  if (songCount > 0) {
    Serial.println('[Player] Ready! Press PLAY on IR Remote to start.');
    Serial.println('[Player] Current: ' + songList[currentSong]);
  } else {
    Serial.println('[Player] Waiting for songs...');
    Serial.println('[Player] Right-click SD Card > Upload files to add .pcm audio.');
  }
}

void loop() {
  // Check IR remote every 50ms
  unsigned long now = millis();
  if (now - lastIrCheck >= IR_CHECK_INTERVAL) {
    lastIrCheck = now;
    handleIRRemote();
  }

  // Play audio
  if (isPlaying && songFile && songFile.available()) {
    int bytesRead = songFile.read(audioBuf, audioBufBytes);
    int samplesRead = bytesRead / 2;

    // Apply volume
    applyVolume(audioBuf, samplesRead);

    // Write to I2S
    size_t bytesWritten = 0;
    i2s_write(I2S_PORT, audioBuf, bytesRead, &bytesWritten, portMAX_DELAY);
  } else if (isPlaying && songFile && !songFile.available()) {
    // Song finished
    Serial.println('[Player] Song finished');
    songFile.close();
    i2s_zero_dma_buffer(I2S_PORT);

    if (repeatAll && songCount > 0) {
      nextSong();
    } else {
      isPlaying = false;
      Serial.println('[Player] Stopped');
    }
  }
}
